/*
 * A320864  Powers of 2 with initial digit 8.
 * https://oeis.org/A320864
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 3, u64 n <= 5, u128 n <= 8,
 *            big any n
 * Helpers:   leading_digit_pow2, pow2
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A320864: Powers of 2 whose initial decimal digit is 8 */

/* The sequence is generated by checking successive powers 2^k.
   A value 2^k is appended to the cache when the most significant
   decimal digit of 2^k is 8.  The leading digit is determined via
   floating‑point logarithms, which do not affect the seq_t value
   itself. */

#include <stdlib.h>
#include <stdbool.h>
#include <math.h>
#include "../utils/pow2.h"
#include "../utils/leading_digit_pow2.h"

/* static cache of computed terms */
static seq_t *cache = NULL;
static size_t  cache_len = 0;
static size_t  cache_cap = 0;

/* the exponent that has been examined most recently */
static idx_t last_exponent = 0;

/* enlarge the cache if needed and append a new term */
static void append_term(idx_t k)
{
    if (cache_len >= cache_cap)
    {
        size_t new_cap = cache_cap ? cache_cap << 1 : 8;
        seq_t *p = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = p;
        cache_cap = new_cap;
    }
    cache[cache_len++] = pow2(k);   /* 2^k */
}

/* ensure we have at least n terms in the cache */
static void ensure_cache(idx_t n)
{
    while (cache_len < n)
    {
        ++last_exponent;
        if (leading_digit_pow2(last_exponent) == 8)
            append_term(last_exponent);
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* offset 1; a(1) is first term */

    ensure_cache(n);
    return cache[n - 1];
}
